  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "Sotalol has an absolute oral bioavailability of 90-100% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Atazanavir has an absolute oral bioavailability of 68% (57-80%) in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Labetalol has a mean systemic bioavailability of 26% in fasting healthy volunteers after oral dosing, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules have numeric human oral bioavailability values at or above approximately 20%, with high assay-transfer scores; therefore the F >= 20% endpoint is supported.",
  "evidence_gaps": [
    "Some records use qualitative descriptors such as 'poor' or 'low' that conflict with numeric F values; numeric absolute measurements were prioritized.",
    "Several records come from altered conditions or special populations, but ordinary-condition human numeric data are available for the key comparisons."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

